#!/usr/bin/env node

/**
 * Generate dynamic vite proxy configuration
 */

const fs = require('fs');
const path = require('path');

const serverPort = process.env.SERVER_PORT || '8787';
const webPort = process.env.WEB_PORT || '5173';

// Generate a Vite server configuration override
const viteServerConfig = `// Auto-generated Vite server configuration
// This file is generated by scripts/generate-vite-config.js
// DO NOT EDIT MANUALLY

export const dynamicServerConfig = {
  port: ${webPort},
  proxy: {
    '/api': {
      target: 'http://127.0.0.1:${serverPort}',
      secure: false,
      changeOrigin: true,
      ws: true,
      configure: (proxy, options) => {
        // Ensure cookies are forwarded for WebSocket connections
        proxy.on('proxyReqWs', (proxyReq, req, socket) => {
          if (req.headers.cookie) {
            proxyReq.setHeader('Cookie', req.headers.cookie);
          }
        });
      }
    }
  }
};
`;

const outputPath = path.join(__dirname, '../apps/web/vite.server.config.js');
fs.writeFileSync(outputPath, viteServerConfig);

console.log(`   Generated vite server config at: ${outputPath}`);